#!/usr/bin/env node
/**
 * Cinejoy webOS - Milestone 4 Independent Forensic & Adversarial Audit
 * tests/forensic-m4.js
 * 
 * Verifies authenticity, absence of facades/hardcoded values,
 * dynamic DOM rendering, true LRU/TTL cache semantics, XSS sanitization,
 * and edge case resilience under stress.
 */

const assert = require('assert');
const path = require('path');
const fs = require('fs');

let JSDOM;
try {
  JSDOM = require('jsdom').JSDOM;
} catch (e1) {
  try {
    JSDOM = require('/home/prem/monkeytype/monkeytype/node_modules/.pnpm/jsdom@27.4.0_supports-color@10.2.2/node_modules/jsdom').JSDOM;
  } catch (e2) {
    JSDOM = require('/home/prem/Documents/movies/netflix/node_modules/jsdom').JSDOM;
  }
}

const tmdbSource = fs.readFileSync(path.resolve(__dirname, '../app/js/tmdb.js'), 'utf8');
const TmdbClient = eval('(function(){ var module = { exports: {} }; ' + tmdbSource + '; return module.exports; })()');

let checksPassed = 0;
let totalChecks = 0;

function runCheck(name, fn) {
  totalChecks++;
  try {
    fn();
    checksPassed++;
    console.log(`  ✓ PASS: ${name}`);
  } catch (err) {
    console.error(`  ✗ FAIL: ${name} -> ${err.message}`);
    throw err;
  }
}

async function runAsyncCheck(name, fn) {
  totalChecks++;
  try {
    await fn();
    checksPassed++;
    console.log(`  ✓ PASS: ${name}`);
  } catch (err) {
    console.error(`  ✗ FAIL: ${name} -> ${err.message}`);
    throw err;
  }
}

async function main() {
  console.log('\n--- FORENSIC AUDIT: LRU/TTL Cache True Semantics ---');

  runCheck('LRU Cache Eviction Order: Accessing item prevents its eviction', () => {
    TmdbClient.init({ cacheCapacity: 3 });
    TmdbClient.clearCache();

    // Fill cache to capacity: keys A, B, C
    TmdbClient.setMockMode(true);
    TmdbClient.setMockFixture('item-a', { id: 'A' });
    TmdbClient.setMockFixture('item-b', { id: 'B' });
    TmdbClient.setMockFixture('item-c', { id: 'C' });
    TmdbClient.setMockFixture('item-d', { id: 'D' });
  });

  await runAsyncCheck('LRU Eviction Order Verification', async () => {
    // 1. Fetch A, B, C
    await TmdbClient.getTrending('item-a');
    await TmdbClient.getTrending('item-b');
    await TmdbClient.getTrending('item-c');

    let stats = TmdbClient.getCacheStats();
    assert.strictEqual(stats.size, 3, 'Cache size should be 3');
    assert.strictEqual(stats.evictions, 0, 'No evictions yet');

    // 2. Access A again to make it Most Recently Used (MRU)
    // Now order from least to most recent should be: B (oldest), C, A (newest)
    await TmdbClient.getTrending('item-a');
    stats = TmdbClient.getCacheStats();
    assert.strictEqual(stats.hits, 1, 'Accessing A should be a cache hit');

    // 3. Add D: Should evict B (the least recently used), NOT A or C
    await TmdbClient.getTrending('item-d');
    stats = TmdbClient.getCacheStats();
    assert.strictEqual(stats.size, 3, 'Cache size should remain capped at capacity 3');
    assert.strictEqual(stats.evictions, 1, 'Should have 1 eviction');

    // 4. Verify A is still cached (hit counter increments), while B is evicted
    await TmdbClient.getTrending('item-a');
    let statsAfterA = TmdbClient.getCacheStats();
    assert.strictEqual(statsAfterA.hits, 2, 'A should still be in cache (hit incremented)');

    // Reset capacity to default
    TmdbClient.init({ cacheCapacity: 100 });
    TmdbClient.clearCache();
    TmdbClient.setMockMode(false);
  });

  console.log('\n--- FORENSIC AUDIT: Normalization & Malformed Data Handling ---');

  runCheck('normalizeItem handles null, undefined, empty, and malformed inputs', () => {
    assert.strictEqual(TmdbClient.normalizeItem(null), null);
    assert.strictEqual(TmdbClient.normalizeItem(undefined), null);

    const empty = TmdbClient.normalizeItem({});
    assert.strictEqual(empty.title, 'Untitled');
    assert.strictEqual(empty.ratingDisplay, 'NR');
    assert.strictEqual(empty.year, '');
    assert.ok(empty.posterUrl.startsWith('data:image/svg+xml'), 'Poster fallback must be SVG');

    const weird = TmdbClient.normalizeItem({
      id: 999,
      vote_average: 'invalid',
      genre_ids: 'not-an-array',
      first_air_date: '2026-11-04'
    });
    assert.strictEqual(weird.type, 'tv');
    assert.strictEqual(weird.ratingDisplay, 'NR');
    assert.strictEqual(weird.year, '2026');
  });

  runCheck('formatRuntime formats hours and minutes properly', () => {
    assert.strictEqual(TmdbClient.formatRuntime(0), '—');
    assert.strictEqual(TmdbClient.formatRuntime(-10), '—');
    assert.strictEqual(TmdbClient.formatRuntime(null), '—');
    assert.strictEqual(TmdbClient.formatRuntime(45), '45m');
    assert.strictEqual(TmdbClient.formatRuntime(60), '1h');
    assert.strictEqual(TmdbClient.formatRuntime(166), '2h 46m');
  });

  console.log('\n--- FORENSIC AUDIT: XSS and HTML Injection in CardFactory ---');

  const dom = new JSDOM('<!DOCTYPE html><html><body><div id="shelf"></div></body></html>');
  const window = dom.window;
  const document = window.document;
  global.window = window;
  global.document = document;
  global.TmdbClient = TmdbClient;

  const homeSource = fs.readFileSync(path.resolve(__dirname, '../app/js/views/home.js'), 'utf8');
  window.eval(homeSource);
  const CardFactory = window.CardFactory;

  runCheck('CardFactory HTML sanitization prevents script injection', () => {
    const maliciousItem = {
      id: 1,
      title: '<script>alert("PWNED")</script>',
      poster_path: '/malicious.jpg',
      year: '2024"><script>alert(1)</script>',
      rating: '8.5',
      genres: ['<b onmouseover="alert(1)">Sci-Fi</b>']
    };

    const card = CardFactory.createPosterCard(maliciousItem, 'test-group', 0);
    const titleEl = card.querySelector('.poster-title');
    assert.strictEqual(titleEl.innerHTML, '&lt;script&gt;alert("PWNED")&lt;/script&gt;');
    assert.strictEqual(titleEl.textContent, '<script>alert("PWNED")</script>');
    assert.strictEqual(card.querySelectorAll('script').length, 0, 'No script tags should be created');
  });

  runCheck('CardFactory createEpisodeCard and createCastCard handle malicious inputs', () => {
    const epCard = CardFactory.createEpisodeCard({
      name: '<img src=x onerror=alert(1)>',
      overview: '<script>evil()</script>',
      runtime: 45
    }, 1, 0);

    assert.strictEqual(epCard.querySelectorAll('script').length, 0);
    assert.ok(epCard.querySelector('.episode-title').innerHTML.indexOf('&lt;img') !== -1);

    const castCard = CardFactory.createCastCard({
      name: '<script>alert("cast")</script>',
      character: 'Hero"><script>'
    }, 0);

    assert.strictEqual(castCard.querySelectorAll('script').length, 0);
    assert.ok(castCard.querySelector('.cast-name').innerHTML.indexOf('&lt;script&gt;') !== -1);
  });

  console.log('\n--- FORENSIC AUDIT: Dynamic Query Formulation & Param Encoding ---');

  await runAsyncCheck('TmdbClient discover query properly encodes special characters & multiple genres', async () => {
    let capturedUrl = '';
    global.fetch = function (url) {
      capturedUrl = url;
      return Promise.resolve({
        ok: true,
        json: () => Promise.resolve({ page: 1, results: [], total_pages: 1, total_results: 0 })
      });
    };

    await TmdbClient.discover('movie', {
      withGenres: [28, 878, 12],
      year: 2024,
      sortBy: 'vote_average.desc',
      voteCountGte: 100,
      withWatchProviders: '8|9|337',
      watchRegion: 'US'
    });

    assert.ok(capturedUrl.indexOf('with_genres=28%2C878%2C12') !== -1 || capturedUrl.indexOf('with_genres=28,878,12') !== -1, 'Multiple genres properly joined and encoded');
    assert.ok(capturedUrl.indexOf('primary_release_year=2024') !== -1, 'Release year set');
    assert.ok(capturedUrl.indexOf('sort_by=vote_average.desc') !== -1, 'Sort order set');
    assert.ok(capturedUrl.indexOf('vote_count.gte=100') !== -1, 'Vote count minimum set');
    assert.ok(capturedUrl.indexOf('with_watch_providers=8%7C9%7C337') !== -1 || capturedUrl.indexOf('with_watch_providers=8|9|337') !== -1, 'Watch providers set');
  });

  console.log(`\n========================================================================`);
  console.log(`FORENSIC AUDIT SUMMARY: ${checksPassed}/${totalChecks} CHECKS PASSED`);
  console.log(`========================================================================\n`);
}

main().catch(err => {
  console.error('Forensic test failed:', err);
  process.exit(1);
});
